using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationComponentEvents : RefCounted
{
    private static Resource Document(RefCounted session)=>session.Get("document").As<Resource>();
    private static Resource? Component(RefCounted session,string id)=>Document(session).Call("component",id).As<Resource>();
    private static string NewId()=>ActorData.new_id();
    private static Resource Make(Vector2I size,string title)=>KiwiTransformationImage2D.make_component(size,title);
    private static Resource Born(Resource target,double at){var key=new KiwiTransformationKey();key.Set("id",NewId());key.Set("time",at);key.Set("state_id",target.Get("default_state_id"));target.Get("keys").AsGodotArray().Add(key);return key;}
    private static void Select(RefCounted session,Resource target){var selected=session.Get("selected").AsGodotArray();selected.Clear();selected.Add(target.Get("id"));}
    public string check_time(RefCounted session,string[] ids,double at){if(!double.IsFinite(at)||at<0||at>Document(session).Get("duration").AsDouble())return "Transfer time is outside the animation.";var seen=new HashSet<string>();foreach(string id in ids){if(!seen.Add(id))return "A transfer cannot contain duplicate sources.";foreach(var raw in Document(session).Get("component_events").AsGodotArray()){var entry=raw.AsGodotDictionary();if(entry["target"].AsString()==id&&entry["time"].AsDouble()>at)return "A transfer cannot occur before its source component is born.";}}return "";}
    public string detach(RefCounted session,Image? mask)
    {
        var item=session.Call("primary").As<Resource>();var state=session.Call("active_state",default(Variant)).As<Resource>();if(item==null||state==null||item.Get("locked").AsBool()||mask==null)return "Select an unlocked component and some pixels first.";double time=session.Get("playhead").AsDouble();string id=item.Get("id").AsString();string timeError=check_time(session,new[]{id},time);if(timeError.Length>0)return timeError;var sample=session.Call("sampled",item,time).AsGodotDictionary();if(sample["a"].AsGodotObject().Get("id").AsString()!=state.Get("id").AsString()||(sample["a"].AsGodotObject()!=sample["b"].AsGodotObject()&&sample["t"].AsDouble()>.00001))return "Detach at an exact state key (or the default state), then choose Edit state.";
        var active=new List<Image>();try{foreach(var raw in Document(session).Get("component_events").AsGodotArray()){var entry=raw.AsGodotDictionary();if(entry["kind"].AsString()!="Split"||Array.IndexOf(entry["sources"].AsStringArray(),id)<0)continue;var pixels=entry["mask"].As<Texture2D>().GetImage();if(pixels==null)return "Existing detach mask is unavailable.";active.Add(pixels);}if(active.Count>=4)return "A component supports four disjoint region detaches. Split another component for more.";using var image=state.Get("artwork").AsGodotObject().Get("texture").As<Texture2D>().GetImage();image.Convert(Image.Format.Rgba8);if(image.GetSize()!=mask.GetSize())return "Selection mask does not match this state artwork.";foreach(var old in active)if(old.GetSize()!=mask.GetSize())old.Resize(mask.GetWidth(),mask.GetHeight(),Image.Interpolation.Nearest);for(int y=0;y<image.GetHeight();y++)for(int x=0;x<image.GetWidth();x++){float amount=mask.GetPixel(x,y).A;foreach(var old in active)if(amount>.01f&&old.GetPixel(x,y).A>.01f)return "Detach regions must not overlap an existing region transfer.";var color=image.GetPixel(x,y);color.A*=amount;image.SetPixel(x,y,color);}if(!image.GetUsedRect().HasArea())return "The selection contains no visible artwork.";var child=Make((Vector2I)item.Get("base_size").AsVector2(),item.Get("title").AsString()+" detached");child.Set("base_size",item.Get("base_size"));var states=child.Get("states").AsGodotArray();var copied=state.Call("copy_state",true).As<Resource>();states[0]=copied;child.Set("default_state_id",copied.Get("id"));var art=copied.Get("artwork").AsGodotObject();art.Set("id",child.Get("id"));var texture=ImageTexture.CreateFromImage(image);art.Set("texture",texture);art.Set("paint_base",texture);Born(child,time);session.Call("begin");var components=Document(session).Get("components").AsGodotArray();components.Insert(components.IndexOf(item)+1,child);Document(session).Get("component_events").AsGodotArray().Add(new Settings {["id"]=NewId(),["kind"]="Split",["time"]=time,["sources"]=new[]{id},["target"]=child.Get("id"),["mask"]=ImageTexture.CreateFromImage(mask)});Select(session,child);session.Call("commit","Detach region at playhead");return "";}finally{foreach(var image in active)image.Dispose();}
    }
    public string merge(RefCounted session,string[] ids,Image? image,double at)
    {
        if(ids.Length<2||image==null||!image.GetUsedRect().HasArea())return "Choose at least two visible components.";if(image.GetSize()!=Document(session).Get("canvas_size").AsVector2I())return "Merge image must match the full canvas.";string error=check_time(session,ids,at);if(error.Length>0)return error;var components=Document(session).Get("components").AsGodotArray();int highest=-1,lowest=components.Count;foreach(string id in ids){var item=Component(session,id);if(item==null||item.Get("locked").AsBool())return "Unlock the selected components before merging.";int index=components.IndexOf(item);highest=Math.Max(highest,index);lowest=Math.Min(lowest,index);}if(highest-lowest+1!=ids.Length)return "Select adjacent components so merging cannot change unrelated compositing order.";var target=Make(Document(session).Get("canvas_size").AsVector2I(),"Merged component");var artwork=target.Get("states").AsGodotArray()[0].AsGodotObject().Get("artwork").AsGodotObject();var texture=ImageTexture.CreateFromImage(image);artwork.Set("texture",texture);artwork.Set("paint_base",texture);Born(target,at);session.Call("begin");components.Insert(highest+1,target);Document(session).Get("component_events").AsGodotArray().Add(new Settings {["id"]=NewId(),["kind"]="Merge",["time"]=at,["sources"]=ids,["target"]=target.Get("id")});Select(session,target);session.Call("commit","Merge components at playhead");return "";
    }
}
